import Foundation
import Vapor
import NIO

// MARK: - Blockchain Smart Contract Event Logger
// This service sits behind an nginx reverse proxy that forwards
// X-Forwarded-For and contract execution metadata

struct ContractEvent: Content {
    let contractAddress: String
    let method: String
    let caller: String
    let params: [String: String]
    let blockNumber: UInt64
}

struct AuditEntry {
    let timestamp: Date
    let message: String
    let severity: Int
}

class ContractAuditLog {
    private var entries: [AuditEntry] = []
    private let lock = NSLock()

    func append(_ entry: AuditEntry) {
        lock.lock()
        defer { lock.unlock() }
        entries.append(entry)
    }

    func query(since: Date) -> [AuditEntry] {
        lock.lock()
        defer { lock.unlock() }
        return entries.filter { $0.timestamp >= since }
    }
}

// MARK: - Format Dispatcher
// Handles log formatting based on proxy-forwarded content-type negotiation

protocol LogFormatter {
    func format(template: String, values: [CVarArg]) -> String
}

class StructuredFormatter: LogFormatter {
    func format(template: String, values: [CVarArg]) -> String {
        // Uses C-style formatting for structured log output
        // compatible with ELK stack ingestion behind the proxy
        return String(format: template, arguments: values)
    }
}

class SafeFormatter: LogFormatter {
    func format(template: String, values: [CVarArg]) -> String {
        // Escapes and uses literal interpolation
        return "[\(template)] -> \(values.map { "\($0)" }.joined(separator: ", "))"
    }
}

// MARK: - Proxy Header Parser

struct ProxyContext {
    let clientIP: String
    let requestID: String
    let formatPreference: String  // from X-Log-Format header set by proxy
}

func parseProxyContext(from req: Request) -> ProxyContext {
    let clientIP = req.headers.first(name: "X-Forwarded-For") ?? "unknown"
    let requestID = req.headers.first(name: "X-Request-ID") ?? UUID().uuidString
    let formatPref = req.headers.first(name: "X-Log-Format") ?? "safe"
    return ProxyContext(clientIP: clientIP, requestID: requestID, formatPreference: formatPref)
}

// MARK: - Contract Execution Validator

func validateContractExecution(_ event: ContractEvent) -> Bool {
    // Basic validation: address format, method whitelist
    guard event.contractAddress.hasPrefix("0x"),
          event.contractAddress.count == 42 else { return false }

    let allowedMethods = ["transfer", "approve", "mint", "burn", "stake", "unstake"]
    guard allowedMethods.contains(event.method) else { return false }

    return true
}

// MARK: - Core Logging Pipeline

func selectFormatter(for context: ProxyContext) -> LogFormatter {
    // The reverse proxy sets X-Log-Format based on downstream consumer
    // "structured" = ELK/Splunk, "safe" = human-readable
    switch context.formatPreference {
    case "structured":
        return StructuredFormatter()
    default:
        return SafeFormatter()
    }
}

func buildLogTemplate(event: ContractEvent, context: ProxyContext) -> (String, [CVarArg]) {
    // Template construction for audit trail
    // The caller field comes from the blockchain event, which is the
    // transaction sender's "display name" registered on-chain
    let template = "[%@] Contract %@ method %@ invoked by %@ from IP %@"
    let values: [CVarArg] = [
        context.requestID,
        event.contractAddress,
        event.method,
        event.caller,      // This is attacker-controlled on-chain data
        context.clientIP
    ]
    return (template, values)
}

func processContractEvent(event: ContractEvent, context: ProxyContext, auditLog: ContractAuditLog) -> String {
    guard validateContractExecution(event) else {
        return "Invalid contract event"
    }

    let formatter = selectFormatter(for: context)
    let (template, values) = buildLogTemplate(event: event, context: context)

    // Here's the critical path: if formatter is StructuredFormatter,
    // it calls String(format:arguments:) with attacker-controlled data
    // in the `values` array. But the TEMPLATE is fixed... or is it?
    //
    // The vulnerability: event.caller is placed in values as a CVarArg,
    // but if the caller registered an on-chain name containing format
    // specifiers like "%@%@%@%@%@%@%@%@%@%@%n", and the template
    // has exactly 5 %@ placeholders, the extra specifiers in the
    // caller value won't cause issues in values... UNLESS we look
    // at the secondary logging path below.

    let formattedMessage = formatter.format(template: template, values: values)

    // Secondary audit: log the raw caller for compliance
    // This path uses the caller directly as a format string
    let complianceNote = buildComplianceNote(event: event, formatter: formatter)

    let entry = AuditEntry(
        timestamp: Date(),
        message: formattedMessage + " | " + complianceNote,
        severity: 1
    )
    auditLog.append(entry)

    return formattedMessage
}

func buildComplianceNote(event: ContractEvent, formatter: LogFormatter) -> String {
    // Compliance requires logging the exact caller identifier
    // We format it with metadata prefix
    let callerNote = "COMPLIANCE_CALLER: " + event.caller
    // BUG: callerNote is used as the template (first arg) to format()
    // If formatter is StructuredFormatter, this becomes:
    //   String(format: "COMPLIANCE_CALLER: <attacker_data>", arguments: [])
    // An attacker who registers on-chain name as "%x%x%x%x%n" gets
    // format string exploitation
    return formatter.format(template: callerNote, values: [])
}

// MARK: - Vapor Route Configuration

func configureRoutes(_ app: Application, auditLog: ContractAuditLog) {
    app.post("api", "v1", "contract", "event") { req -> String in
        let event = try req.content.decode(ContractEvent.self)
        let context = parseProxyContext(from: req)
        return processContractEvent(event: event, context: context, auditLog: auditLog)
    }

    app.get("api", "v1", "audit") { req -> String in
        let since = Date().addingTimeInterval(-3600)
        let entries = auditLog.query(since: since)
        return entries.map { $0.message }.joined(separator: "\n")
    }
}
